CREATE TABLE "mailbox" (
  "mailbox_id" SMALLINT NOT NULL,
  "name" VARCHAR(64) NOT NULL,
  PRIMARY KEY ("mailbox_id")
);

CREATE TABLE "message" (
  "id" INTEGER NOT NULL,
  "mailbox_id" SMALLINT NOT NULL,
  "folder" VARCHAR(255) NOT NULL,
  "path" VARCHAR(255) NOT NULL,
  "message_id" VARCHAR(255),
  "date_utc" DATETIME,
  "date_raw" VARCHAR(64),
  "from_address" VARCHAR(255),
  "from_raw" VARCHAR(1000),
  "subject" TEXT,
  "body" TEXT,
  "body_sha1" CHAR(40),
  "x_from" TEXT,
  "x_to" TEXT,
  "x_cc" TEXT,
  "x_bcc" TEXT,
  "x_folder" TEXT,
  "x_origin" TEXT,
  "x_filename" TEXT,
  "charset_fallback" TINYINT NOT NULL DEFAULT 0,
  "header_defects" SMALLINT NOT NULL DEFAULT 0,
  PRIMARY KEY ("id"),
  CONSTRAINT "fk_message_mailbox" FOREIGN KEY ("mailbox_id") REFERENCES "mailbox" ("mailbox_id") ON UPDATE NO ACTION ON DELETE NO ACTION
);

CREATE TABLE "recipient" (
  "message_id" INTEGER NOT NULL,
  "kind" TEXT NOT NULL CHECK ("kind" IN ('to', 'cc', 'bcc')),
  "position" SMALLINT NOT NULL,
  "address" VARCHAR(255) NOT NULL,
  "display_name" VARCHAR(255),
  PRIMARY KEY ("message_id", "kind", "position"),
  CONSTRAINT "fk_recipient_message" FOREIGN KEY ("message_id") REFERENCES "message" ("id") ON UPDATE NO ACTION ON DELETE CASCADE
);

CREATE UNIQUE INDEX "mailbox_uq_mailbox_name" ON "mailbox" ("name");
